    static let separadorDeClausula = "(?<!\\d),(?!\\d)|\\b(e sim|e|mas|por[ée]m|ou)\\b|;"
    /// Abertura de cláusula ADVERSATIVA: ela QUALIFICA a oração anterior em
    /// vez de afirmar coisa nova. Com slot de advérbio, porque o fabricador
    /// derrubou as três variantes de `— sempre mas não pela folha`.
    static let adversativaInicial = "^\\s*((?:([0-9A-Za-zÀ-ÿ_]+mente|assim|sempre|hoje|logo|j[áa]|ainda|mesmo|s[óo]))\\s+)*(mas|por[ée]m|e sim)(?![0-9A-Za-zÀ-ÿ])"
    /// Negador COLADO no destinatário. Sem o `sem`: ver `_porque_negadores`.
    static let negadorColado = "^\\s*((?:([0-9A-Za-zÀ-ÿ_]+mente|assim|sempre|hoje|logo|j[áa]|ainda|mesmo|s[óo]))\\s+)*(que\\s+)?(n[ãa]o|nunca|nem|jamais|not|never|jam[áa]s|ni)\\b"
    /// A frase que o produto diz. Não é uma variação.
    static let sancionada = "o restaurante distribui à equipe, como manda a lei"
}
